-- Gold Query
SELECT t2.player_name FROM Player_Attributes AS t1 INNER JOIN Player AS t2 ON t1.id = t2.id ORDER BY t1.penalties DESC, t1.id NULLS LAST, t2.id NULLS LAST LIMIT 10;

